  auth-provider.tsx       # Auth provider component
lib/
  auth/
    client.ts             # Auth client export
```

### React SPA

```
src/
  lib/
    auth-client.ts        # Auth client with adapter
  providers.tsx           # Auth provider component
  App.tsx                # Routes
  main.tsx               # Entry point with BrowserRouter
```

